// thin wrapper over the Pagefind JS API generated by `pagefind --site dist` after the build.
// In `astro dev` there is no index; `loadPagefind()` then resolves to null and the UI stays inert.
export interface PagefindSubResult {
  title: string;
  url: string;
  excerpt: string;
}
export interface PagefindResultData {
  url: string;
  excerpt: string;
  meta: { title?: string; [key: string]: string | undefined };
  sub_results: PagefindSubResult[];
}
export interface PagefindResult {
  id: string;
  data(): Promise<PagefindResultData>;
}
export interface Pagefind {
  init(): Promise<void>;
  options(opts: Record<string, unknown>): Promise<void>;
  search(
    query: string,
    opts?: { filters?: Record<string, string> }
  ): Promise<{ results: PagefindResult[] }>;
  preload(query: string): Promise<void>;
}

const base = `${import.meta.env.BASE_URL.replace(/\/$/, '')}/`;
let loader: Promise<Pagefind | null> | undefined;

export function loadPagefind(): Promise<Pagefind | null> {
  loader ??= (async () => {
    try {
      const url = `${base}pagefind/pagefind.js`;
      const pagefind = (await import(/* @vite-ignore */ url)) as Pagefind;
      await pagefind.options({ baseUrl: base, excerptLength: 30 });
      await pagefind.init();
      return pagefind;
    } catch (error) {
      console.warn('[search] Pagefind index unavailable', error);
      return null;
    }
  })();
  return loader;
}

export const SEARCH_RESULT_LIMIT = 15;

export interface Hit {
  type: 'title' | 'heading' | 'content';
  title: string;
  url: string;
  pageTitle: string;
  isInterOfTree: boolean;
  isLastOfTree: boolean;
}

/** Flattens Pagefind results into the title + sub-result rows of the suggestion list (max 15). */
export async function searchHits(
  pagefind: Pagefind,
  query: string,
  filters: Record<string, string>
): Promise<Hit[]> {
  const { results } = await pagefind.search(query, { filters });
  const hits: Hit[] = [];
  for (const result of results) {
    if (hits.length >= SEARCH_RESULT_LIMIT) break;
    const data = await result.data();
    const clean = (t: string) => t.replace(/[\u200B-\u200D\uFEFF]/g, '').trim(); // headings carry the hash-link's zero-width space
    const pageTitle = clean(data.meta.title ?? data.url);
    const subs = data.sub_results
      .filter((s) => s.url !== data.url && s.title !== pageTitle)
      .slice(0, 3);
    hits.push({
      type: 'title',
      title: pageTitle,
      url: data.url,
      pageTitle,
      isInterOfTree: false,
      isLastOfTree: false,
    });
    subs.forEach((sub, i) => {
      if (hits.length >= SEARCH_RESULT_LIMIT) return;
      hits.push({
        type: 'heading',
        title: sub.title,
        url: sub.url,
        pageTitle,
        isInterOfTree: i < subs.length - 1,
        isLastOfTree: i === subs.length - 1,
      });
    });
  }
  return hits;
}

export function highlight(text: string, query: string): string {
  const tokens = query.split(/\s+/).filter(Boolean);
  const escaped = text.replace(
    /[&<>"']/g,
    (c) =>
      ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[
        c
      ]!
  );
  if (tokens.length === 0) return escaped;
  const re = new RegExp(
    `(${tokens.map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|')})`,
    'gi'
  );
  return escaped.replace(re, '<mark>$1</mark>');
}
